<?php

namespace Database\Seeders;

use App\Domains\Guides\Models\Guide;
use Illuminate\Database\Seeder;

/**
 * EXPA content expansion V7: practical starter guides for health, education,
 * housing, transport, family services and everyday finances.
 * Official links are provided for verification; production content stays in review.
 */
class OfficialContentV7Seeder extends Seeder
{
    private const VERIFIED_AT = '2026-10-10';

    public function run(): void
    {
        foreach ($this->items() as $index => $item) {
            $guide = Guide::updateOrCreate(['slug' => $item['slug']], [
                'category' => $item['category'],
                'italian_term' => $item['term'],
                'sort_order' => 4000 + ($index * 10),
                'source_name' => $item['source'],
                'source_url' => $item['url'],
                'source_type' => 'official',
                'last_verified_at' => self::VERIFIED_AT,
            ]);

            $guide->setTranslations($item['translations']);
            $local = app()->environment('local', 'testing');
            $guide->forceFill([
                'status' => $local ? 'published' : 'review',
                'published_at' => $local ? ($guide->published_at ?? now()) : null,
            ])->save();
        }
    }

    private function tr(array $ar, array $en, array $it): array
    {
        return ['ar' => $ar, 'en' => $en, 'it' => $it];
    }

    private function guide(
        string $title,
        string $summary,
        string $what,
        string $who,
        array $docs,
        array $steps,
        string $where,
        string $cost,
        string $time,
        string $body,
    ): array {
        return [
            'title' => $title,
            'summary' => $summary,
            'what_is' => $what,
            'who_needs' => $who,
            'required_documents' => $docs,
            'steps' => $steps,
            'where_to_apply' => $where,
            'costs' => $cost,
            'processing_time' => $time,
            'body' => $body,
        ];
    }

    private function items(): array
    {
        return [
            [
                'slug' => 'register-with-ssn-and-choose-family-doctor',
                'category' => 'healthcare',
                'term' => 'Iscrizione al SSN e scelta del medico di base',
                'source' => 'Ministero della Salute',
                'url' => 'https://www.salute.gov.it/',
                'translations' => $this->tr(
                    $this->guide('التسجيل في SSN واختيار طبيب الأسرة', 'خطوات أولية لفهم التسجيل في الخدمة الصحية الإيطالية واختيار طبيب الأسرة.', 'الخدمة الصحية الوطنية SSN تنظّم الوصول إلى خدمات صحية عامة. أهلية التسجيل والوثائق تختلف حسب الإقامة والعمل والحالة الشخصية والمنطقة.', 'القادمون إلى إيطاليا والمقيمون الذين يحتاجون إلى معرفة جهة التسجيل الصحي.', ['وثيقة هوية وجواز سفر عند الاقتضاء', 'Codice Fiscale', 'تصريح الإقامة أو إيصال الطلب إذا طُلب', 'إثبات العمل أو الدراسة أو سبب الأهلية حسب الحالة'], [['تحقق من أهليتك', 'راجع وزارة الصحة وموقع المنطقة لمعرفة هل التسجيل إلزامي أم اختياري لحالتك.'], ['اعرف مكتب التسجيل المحلي', 'ابحث عن ASL المختصة بعنوان سكنك واسأل عن قائمة الوثائق الحالية.'], ['قدّم الطلب', 'أرسل المستندات المطلوبة واحتفظ بإثبات التسجيل.'], ['اختر طبيب الأسرة', 'تحقق من الأطباء المتاحين وإجراءات الاختيار أو التغيير لدى ASL.']], 'ASL المحلية وموقع الخدمات الصحية في منطقتك.', 'قد يكون التسجيل مجانيًا أو خاضعًا لمساهمة حسب وضعك؛ لا تفترض الإعفاء قبل التحقق.', 'يعتمد على ASL واكتمال المستندات.', 'القواعد قد تختلف بين المناطق وتتغير بحسب نوع الإقامة. للحالات العاجلة لا تنتظر اكتمال إجراءات التسجيل؛ استخدم خدمات الطوارئ المناسبة.',),
                    $this->guide('Register with the SSN and choose a family doctor', 'A starter guide to Italy’s National Health Service registration and choosing a family doctor.', 'The Servizio Sanitario Nazionale (SSN) organises access to public healthcare. Eligibility and documents depend on residence, work, personal circumstances and region.', 'New arrivals and residents who need to understand where to register for healthcare.', ['Identity document and passport where applicable', 'Codice Fiscale', 'Residence permit or application receipt if requested', 'Evidence of work, study or another qualifying basis, as applicable'], [['Check eligibility', 'Consult the Ministry of Health and your region to see whether registration is mandatory or voluntary for your situation.'], ['Find your local office', 'Identify the ASL responsible for your address and request its current document checklist.'], ['Submit the application', 'Provide the requested documents and keep proof of registration.'], ['Choose a family doctor', 'Check available doctors and the ASL process for choosing or changing one.']], 'Your local ASL and regional health-service website.', 'Registration may be free or subject to a contribution depending on status; confirm eligibility for exemption.', 'Depends on the ASL and whether the file is complete.', 'Rules can vary by region and residence status. For urgent needs, do not delay emergency care while waiting for registration.',),
                    $this->guide('Iscrizione al SSN e scelta del medico di base', 'Guida introduttiva all’iscrizione al Servizio Sanitario Nazionale e alla scelta del medico di base.', 'Il SSN organizza l’accesso alla sanità pubblica. Requisiti e documenti dipendono da residenza, lavoro, situazione personale e regione.', 'Nuovi arrivati e residenti che devono capire dove iscriversi al servizio sanitario.', ['Documento d’identità e passaporto, se necessario', 'Codice Fiscale', 'Permesso di soggiorno o ricevuta, se richiesti', 'Prova di lavoro, studio o altro requisito applicabile'], [['Verifica i requisiti', 'Consulta il Ministero della Salute e la tua regione per capire se l’iscrizione è obbligatoria o volontaria.'], ['Individua l’ufficio locale', 'Trova la ASL competente per il tuo indirizzo e chiedi l’elenco aggiornato dei documenti.'], ['Presenta la domanda', 'Consegna i documenti richiesti e conserva la prova d’iscrizione.'], ['Scegli il medico di base', 'Verifica i medici disponibili e la procedura ASL per scegliere o cambiare medico.']], 'ASL locale e sito del servizio sanitario regionale.', 'L’iscrizione può essere gratuita o prevedere un contributo secondo la situazione; verifica eventuali esenzioni.', 'Dipende dalla ASL e dalla completezza della pratica.', 'Le regole variano per regione e status. Per necessità urgenti non rimandare l’assistenza d’emergenza in attesa dell’iscrizione.')
                ),
            ],
            [
                'slug' => 'enrol-in-italian-university-international-student',
                'category' => 'study',
                'term' => 'Iscrizione universitaria per studenti internazionali',
                'source' => 'Universitaly / Ministero dell’Università e della Ricerca',
                'url' => 'https://www.universitaly.it/',
                'translations' => $this->tr(
                    $this->guide('التقديم للجامعة في إيطاليا للطلاب الدوليين', 'خريطة عامة للتحقق من شروط القبول واللغة والوثائق والمنح قبل التقديم.', 'كل جامعة وبرنامج يحددان شروط القبول والمواعيد واللغة والمستندات. إجراءات التأشيرة أو الاعتراف بالشهادة منفصلة عن قرار القبول.', 'الطلاب الدوليون الذين يبحثون عن برنامج بكالوريوس أو ماجستير أو مسار آخر.', ['جواز سفر ووثائق الهوية', 'الشهادة السابقة وكشف الدرجات', 'ترجمة أو تصديق أو بيان قيمة الشهادة إذا طلبته الجامعة', 'إثبات اللغة عند اشتراطه', 'ملف التقديم وأي مستندات خاصة بالبرنامج'], [['اختر البرنامج والجامعة', 'تحقق من شروط البرنامج واللغة والمواعيد على موقع الجامعة.'], ['راجع Universitaly', 'استخدم البوابة الرسمية عندما تنطبق إجراءاتها على مسارك.'], ['جهّز الشهادات', 'لا تطلب ترجمة أو تصديقًا مكلفًا قبل التأكد من متطلبات الجامعة والبلد المصدر.'], ['تحقق من المنح والرسوم', 'راجع مكتب الطلاب الدوليين ومكتب المنح والمنطقة قبل الموعد النهائي.'], ['تابع خطوات ما بعد القبول', 'تحقق منفصلًا من إجراءات التأشيرة والإقامة والتسجيل النهائي إن كانت تنطبق.']], 'موقع الجامعة الرسمي وUniversitaly ومكتب الطلاب الدوليين.', 'الرسوم والمنح تختلف حسب الجامعة والبرنامج والدخل والقواعد الإقليمية.', 'المواعيد تختلف حسب البرنامج والجنسية وإجراءات القبول.', 'لا تعتبر القبول الجامعي بديلًا عن التأشيرة أو تصريح الإقامة. استخدم دائمًا إعلان القبول للسنة الدراسية المعنية.',),
                    $this->guide('Applying to an Italian university as an international student', 'A roadmap for checking admission, language, documents and scholarships before applying.', 'Each university and programme sets its own entry requirements, deadlines, language and documents. Visa procedures and qualification recognition are separate from admission.', 'International students considering a bachelor’s, master’s or another programme.', ['Passport and identity documents', 'Previous qualification and transcript', 'Translation, legalisation or qualification statement if required', 'Language evidence where required', 'Application file and programme-specific documents'], [['Choose a programme and university', 'Check entry rules, language and deadlines on the university website.'], ['Check Universitaly', 'Use the official portal where its procedures apply to your route.'], ['Prepare qualifications', 'Do not pay for translations or legalisation until you confirm the university and issuing-country requirements.'], ['Check scholarships and fees', 'Contact international student and scholarship offices and check regional deadlines.'], ['Follow post-admission steps', 'Separately verify visa, residence and final-enrolment requirements if applicable.']], 'The university website, Universitaly and the international student office.', 'Tuition and scholarships vary by university, programme, income and regional rules.', 'Deadlines vary by programme, nationality and admission route.', 'Admission does not replace a visa or residence permit. Always use the call for applications for the relevant academic year.',),
                    $this->guide('Iscrizione universitaria in Italia per studenti internazionali', 'Percorso per verificare ammissione, lingua, documenti e borse di studio prima della candidatura.', 'Ogni università e corso definisce requisiti, scadenze, lingua e documenti. Le procedure per visto e riconoscimento dei titoli sono distinte dall’ammissione.', 'Studenti internazionali interessati a lauree triennali, magistrali o altri percorsi.', ['Passaporto e documenti d’identità', 'Titolo di studio precedente e transcript', 'Traduzione, legalizzazione o attestazione del titolo se richiesta', 'Prova linguistica, se prevista', 'Domanda e documenti specifici del corso'], [['Scegli corso e università', 'Controlla requisiti, lingua e scadenze sul sito ufficiale.'], ['Consulta Universitaly', 'Usa il portale ufficiale quando la procedura si applica al tuo percorso.'], ['Prepara i titoli', 'Non pagare traduzioni o legalizzazioni prima di confermare i requisiti.'], ['Verifica borse e tasse', 'Contatta gli uffici internazionali e borse di studio e controlla le scadenze regionali.'], ['Segui i passaggi dopo l’ammissione', 'Verifica separatamente visto, permesso e immatricolazione finale, se applicabili.']], 'Sito ufficiale dell’università, Universitaly e ufficio studenti internazionali.', 'Tasse e borse variano in base a università, corso, reddito e regole regionali.', 'Le scadenze dipendono da corso, cittadinanza e procedura.', 'L’ammissione non sostituisce visto o permesso di soggiorno. Consulta sempre il bando dell’anno accademico pertinente.')
                ),
            ],
            [
                'slug' => 'rental-contract-registration-and-deposit',
                'category' => 'housing',
                'term' => 'Registrazione del contratto di locazione',
                'source' => 'Agenzia delle Entrate',
                'url' => 'https://www.agenziaentrate.gov.it/',
                'translations' => $this->tr(
                    $this->guide('عقد الإيجار والتسجيل والتأمين', 'ما الذي ينبغي مراجعته قبل دفع الوديعة أو توقيع عقد السكن.', 'عقد الإيجار يحدد مدة السكن والإيجار والالتزامات. قواعد التسجيل والضرائب والاستثناءات تعتمد على نوع العقد؛ اطلب نسخة موقعة وإثباتات الدفع.', 'المستأجرون الجدد والطلاب والعائلات التي تستأجر منزلًا أو غرفة.', ['هوية الأطراف وCodice Fiscale عند الحاجة', 'نسخة العقد وجميع الملاحق', 'إثبات دفع الوديعة والإيجار', 'محضر حالة السكن وقراءات العدادات عند الانتقال'], [['تحقق من هوية المؤجر وصلاحيته', 'تأكد من أن الشخص مخوّل بتأجير العقار واطلب تفاصيل مكتوبة.'], ['اقرأ العقد كاملًا', 'راجع المدة والإيجار والمصاريف والوديعة والإشعار المبكر وشروط الإنهاء.'], ['اسأل عن التسجيل', 'تحقق من مسؤولية التسجيل والموعد والرسوم لدى Agenzia delle Entrate.'], ['وثّق حالة المنزل', 'التقط صورًا مؤرخة وسجل العيوب والعدادات عند الاستلام.'], ['احتفظ بالإيصالات', 'استخدم وسيلة دفع قابلة للتتبع واحتفظ بالعقد وإثبات التسجيل والمراسلات.']], 'Agenzia delle Entrate ومراكز المساعدة المؤهلة؛ استعن بمستشار عند وجود نزاع.', 'تختلف الضرائب والرسوم حسب العقد والنظام المختار؛ تحقق من القواعد الحالية.', 'يجب احترام المواعيد القانونية الخاصة بنوع العقد؛ تحقق منها قبل التوقيع.', 'لا تدفع مبالغ كبيرة دون عقد أو إثبات. لا تعتمد على قاعدة عامة بشأن الوديعة أو الإنهاء دون مراجعة نوع العقد والقانون الساري.',),
                    $this->guide('Rental contracts, registration and deposits', 'What to review before paying a deposit or signing a housing agreement in Italy.', 'A rental contract sets the term, rent and obligations. Registration, tax and exceptions depend on the contract type; keep a signed copy and payment evidence.', 'New tenants, students and families renting a home or room.', ['Parties’ identity details and Codice Fiscale where needed', 'Signed contract and attachments', 'Proof of deposit and rent payments', 'Move-in condition report and meter readings'], [['Verify the landlord’s authority', 'Confirm the person is entitled to rent the property and request written details.'], ['Read the full agreement', 'Check term, rent, extra charges, deposit, notice and termination clauses.'], ['Ask about registration', 'Confirm who registers the contract, the deadline and fees with Agenzia delle Entrate.'], ['Record the property condition', 'Take dated photos and note defects and meter readings at move-in.'], ['Keep receipts', 'Use traceable payments and retain the contract, registration proof and messages.']], 'Agenzia delle Entrate and qualified housing-support services; seek advice if there is a dispute.', 'Taxes and fees depend on contract type and chosen regime; check current rules.', 'Legal deadlines depend on the contract type; verify them before signing.', 'Avoid large payments without a contract or proof. Do not rely on a generic deposit or termination rule without checking the agreement and current law.',),
                    $this->guide('Contratto di locazione, registrazione e deposito', 'Cosa controllare prima di versare una cauzione o firmare un contratto abitativo.', 'Il contratto definisce durata, canone e obblighi. Registrazione, imposte ed eccezioni dipendono dal tipo di contratto; conserva copia firmata e prove di pagamento.', 'Nuovi inquilini, studenti e famiglie che affittano un appartamento o una stanza.', ['Dati identificativi delle parti e Codice Fiscale, se necessario', 'Contratto firmato e allegati', 'Prove del deposito e dei canoni pagati', 'Verbale sullo stato dell’alloggio e letture dei contatori'], [['Verifica i poteri del locatore', 'Accertati che possa locare l’immobile e chiedi i dettagli per iscritto.'], ['Leggi tutto il contratto', 'Controlla durata, canone, spese, cauzione, preavviso e recesso.'], ['Chiedi informazioni sulla registrazione', 'Conferma responsabile, scadenza e costi con l’Agenzia delle Entrate.'], ['Documenta lo stato dell’immobile', 'Scatta foto datate e annota difetti e contatori all’ingresso.'], ['Conserva le ricevute', 'Usa pagamenti tracciabili e conserva contratto, registrazione e messaggi.']], 'Agenzia delle Entrate e servizi qualificati di assistenza abitativa; chiedi consulenza in caso di controversia.', 'Imposte e costi dipendono dal contratto e dal regime scelto; verifica le regole aggiornate.', 'Le scadenze legali dipendono dal tipo di contratto; verificale prima della firma.', 'Evita pagamenti importanti senza contratto o prova. Non applicare regole generiche su cauzione o recesso senza verificare contratto e normativa vigente.')
                ),
            ],
            [
                'slug' => 'public-transport-tickets-and-fines',
                'category' => 'daily_life',
                'term' => 'Biglietti e abbonamenti del trasporto pubblico',
                'source' => 'ATAC Roma',
                'url' => 'https://www.atac.roma.it/',
                'translations' => $this->tr(
                    $this->guide('المواصلات العامة: التذاكر والاشتراكات والمخالفات', 'تعرّف على طريقة اختيار التذكرة والتحقق من صلاحيتها وتجنب الغرامات.', 'تختلف صلاحية التذاكر والأسعار وطرق التحقق بين المدن ومشغلي النقل. في روما راجع ATAC والجهات الرسمية قبل السفر.', 'المقيمون والطلاب والزوار الذين يستخدمون الحافلات والمترو والقطارات المحلية.', ['بطاقة هوية عند طلب اشتراك شخصي أو تخفيض', 'إثبات الأهلية للتخفيض إن وجد', 'التذكرة أو الاشتراك الصالح طوال الرحلة'], [['حدد المدينة والمشغل', 'تحقق من المنطقة التي تغطيها التذكرة ووسائل النقل المشمولة.'], ['اشترِ من قناة معتمدة', 'استخدم التطبيق أو الآلات أو نقاط البيع الرسمية.'], ['تحقق من التفعيل والصلاحية', 'فعّل التذكرة بالطريقة المطلوبة واحتفظ بها طوال الرحلة.'], ['اقرأ شروط الاشتراك والتخفيض', 'تحقق من المستندات المطلوبة وشروط التجديد.'], ['إذا تلقيت مخالفة', 'راجع السبب والموعد وطريقة الاعتراض أو الدفع على الموقع الرسمي.']], 'في روما: ATAC؛ وفي المدن الأخرى: مشغل النقل المحلي والجهة الإقليمية.', 'الأسعار والتخفيضات تتغير؛ تحقق من التعريفة الرسمية الحالية.', 'تعتمد صلاحية التذكرة على النوع والمنطقة ووقت التفعيل.', 'لا تفترض أن لقطة شاشة أو إيصال شراء بديل عن تذكرة مفعلة إذا كانت الشروط تتطلب ذلك. راجع قواعد المشغل قبل الرحلة.',),
                    $this->guide('Public transport: tickets, passes and fines', 'Learn how to choose a ticket, check its validity and reduce the risk of a fine.', 'Ticket validity, fares and validation methods differ by city and operator. In Rome, check ATAC and official transport information before travelling.', 'Residents, students and visitors using buses, metro and local trains.', ['Identity document for personalised passes or discounts when requested', 'Proof of discount eligibility if applicable', 'Valid ticket or pass for the entire journey'], [['Identify the city and operator', 'Check the zones and transport modes covered by the ticket.'], ['Buy through an authorised channel', 'Use the official app, machines or authorised retailers.'], ['Validate and check validity', 'Activate the ticket as required and keep it for the journey.'], ['Read pass and discount conditions', 'Check required evidence and renewal rules.'], ['If you receive a fine', 'Check the reason, deadline and official payment or appeal process.']], 'In Rome: ATAC; elsewhere: the local operator and regional authority.', 'Fares and discounts change; check the current official fare table.', 'Validity depends on ticket type, zone and activation time.', 'A screenshot or purchase receipt may not replace a validated ticket where validation is required. Check operator rules before travelling.',),
                    $this->guide('Trasporto pubblico: biglietti, abbonamenti e sanzioni', 'Come scegliere il titolo di viaggio, verificarne la validità e ridurre il rischio di sanzioni.', 'Validità, tariffe e modalità di convalida cambiano secondo città e operatore. A Roma consulta ATAC e le informazioni ufficiali prima di viaggiare.', 'Residenti, studenti e visitatori che usano autobus, metro e treni locali.', ['Documento d’identità per abbonamenti nominativi o agevolazioni, se richiesto', 'Prova dei requisiti per lo sconto, se applicabile', 'Biglietto o abbonamento valido per l’intero viaggio'], [['Individua città e operatore', 'Controlla zone e mezzi inclusi nel titolo di viaggio.'], ['Acquista da un canale autorizzato', 'Usa app, distributori o rivenditori ufficiali.'], ['Convalida e verifica la validità', 'Attiva il biglietto come richiesto e conservalo durante il viaggio.'], ['Leggi condizioni di abbonamenti e sconti', 'Controlla documenti richiesti e rinnovi.'], ['Se ricevi una sanzione', 'Verifica motivo, scadenza e procedura ufficiale di pagamento o ricorso.']], 'A Roma: ATAC; altrove: operatore locale e autorità regionale.', 'Tariffe e agevolazioni cambiano; consulta il tariffario ufficiale aggiornato.', 'La validità dipende da tipo di titolo, zona e attivazione.', 'Uno screenshot o una ricevuta d’acquisto può non sostituire un titolo convalidato quando richiesto. Verifica le regole prima di viaggiare.')
                ),
            ],
            [
                'slug' => 'isee-dsu-document-preparation',
                'category' => 'money',
                'term' => 'ISEE e Dichiarazione Sostitutiva Unica (DSU)',
                'source' => 'INPS',
                'url' => 'https://www.inps.it/',
                'translations' => $this->tr(
                    $this->guide('ISEE وDSU: تجهيز المستندات', 'قائمة تحضير عامة قبل طلب حساب ISEE للاستفادة من خدمات أو تخفيضات مرتبطة بالدخل.', 'ISEE مؤشر يعتمد على بيانات الأسرة والدخل والأصول وفق قواعد محددة. تُستخدم DSU لتقديم البيانات، وقد تختلف الوثائق المطلوبة حسب الأسرة والحالة.', 'الأسر والطلاب ومن يتقدمون لمنافع أو رسوم مخفضة تتطلب ISEE.', ['وثائق الهوية وCodice Fiscale لأفراد الأسرة', 'بيانات الدخل للفترة المرجعية المطلوبة', 'أرصدة وحركات الحسابات والأصول المالية للفترة المحددة', 'بيانات العقارات والإيجار والرهون عند انطباقها', 'مستندات خاصة بالحالة الأسرية إذا طُلبت'], [['حدد نوع ISEE المطلوب', 'قد تختلف القواعد حسب الجامعة أو الخدمة أو المنفعة.'], ['اجمع بيانات الأسرة', 'تحقق من تكوين nucleo familiare وفق القواعد لا حسب العنوان وحده.'], ['جهز بيانات الدخل والأصول', 'استخدم الفترة المرجعية الصحيحة التي تحددها تعليمات INPS الحالية.'], ['قدّم DSU عبر القناة الرسمية أو CAF', 'راجع البيانات قبل الإرسال واحتفظ بالإيصال.'], ['تحقق من النتيجة والموعد', 'تأكد من صحة الشهادة وأنها صالحة للخدمة التي ستطلبها.']], 'INPS أو CAF معتمد، مع مراجعة تعليمات الجهة التي تطلب ISEE.', 'قد تكون المساعدة عبر CAF مجانية أو خاضعة لشروط الخدمة؛ اسأل قبل الموعد.', 'تعتمد على اكتمال البيانات ومعالجة الطلب.', 'لا تستخدم بيانات سنة أو أفراد أسرة غير صحيحة. تختلف مكونات ISEE والوثائق بحسب الحالة؛ اطلب مساعدة مختصة عند وجود دخل أو أصول خارج إيطاليا.',),
                    $this->guide('ISEE and DSU: preparing your documents', 'A general checklist before requesting an ISEE assessment for income-related benefits or reduced fees.', 'ISEE measures household economic circumstances under defined rules. The DSU is used to submit information; the required documents depend on the household and situation.', 'Families, students and applicants for benefits or reduced fees that require ISEE.', ['Identity documents and Codice Fiscale for household members', 'Income data for the relevant reference period', 'Bank balances, account movements and financial assets for the specified period', 'Property, rent and mortgage information where applicable', 'Household-specific evidence if requested'], [['Identify the required ISEE type', 'Requirements may differ for university, services or specific benefits.'], ['Collect household information', 'Determine the nucleo familiare under the rules, not by address alone.'], ['Prepare income and asset data', 'Use the reference period specified by current INPS instructions.'], ['Submit the DSU through an official channel or CAF', 'Review entries before submitting and keep the receipt.'], ['Check the result and validity', 'Make sure the certificate is correct and valid for the service you need.']], 'INPS or an authorised CAF, and the office requesting the ISEE.', 'CAF assistance may be free or subject to service conditions; ask before the appointment.', 'Depends on complete information and processing.', 'Do not use incorrect years or household members. ISEE components and documents vary; seek qualified help if you have income or assets abroad.',),
                    $this->guide('ISEE e DSU: preparare i documenti', 'Checklist generale per richiedere l’ISEE per agevolazioni o tariffe legate alla situazione economica.', 'L’ISEE misura la situazione economica del nucleo secondo regole definite. La DSU serve a dichiarare i dati; i documenti dipendono dal nucleo e dal caso.', 'Famiglie, studenti e persone che richiedono prestazioni o tariffe agevolate con ISEE.', ['Documenti d’identità e Codice Fiscale dei componenti', 'Dati reddituali del periodo di riferimento', 'Saldi, giacenze e patrimoni finanziari del periodo previsto', 'Dati su immobili, affitto e mutui, se applicabili', 'Documenti specifici del nucleo, se richiesti'], [['Individua il tipo di ISEE', 'I requisiti possono cambiare per università, servizi o prestazioni specifiche.'], ['Raccogli i dati del nucleo', 'Determina il nucleo familiare secondo le regole, non solo in base all’indirizzo.'], ['Prepara redditi e patrimoni', 'Usa il periodo di riferimento previsto dalle istruzioni INPS aggiornate.'], ['Invia la DSU tramite canale ufficiale o CAF', 'Controlla i dati e conserva la ricevuta.'], ['Verifica risultato e validità', 'Assicurati che l’attestazione sia corretta e valida per il servizio richiesto.']], 'INPS o CAF autorizzato e ufficio che richiede l’ISEE.', 'L’assistenza CAF può essere gratuita o soggetta a condizioni; chiedi prima dell’appuntamento.', 'Dipende dalla completezza dei dati e dai tempi di elaborazione.', 'Non indicare anni o componenti del nucleo in modo errato. Documenti e componenti ISEE variano; chiedi assistenza qualificata in caso di redditi o patrimoni esteri.')
                ),
            ],
            [
                'slug' => 'family-reunification-first-checklist',
                'category' => 'immigration',
                'term' => 'Ricongiungimento familiare',
                'source' => 'Ministero dell’Interno',
                'url' => 'https://www.interno.gov.it/',
                'translations' => $this->tr(
                    $this->guide('لمّ الشمل العائلي: قائمة البداية', 'افهم المتطلبات التي ينبغي التحقق منها قبل تقديم طلب لمّ الشمل.', 'لمّ الشمل يخضع لشروط تتعلق بنوع الإقامة والعلاقة الأسرية والدخل والسكن والوثائق. المتطلبات تختلف بحسب الحالة والقواعد السارية.', 'المقيمون في إيطاليا الذين يرغبون في تقديم طلب لأفراد الأسرة المؤهلين.', ['جوازات السفر ووثائق الهوية', 'وثائق تثبت العلاقة الأسرية حسب الحالة', 'تصريح الإقامة ووثائق الدخل المطلوبة', 'وثائق السكن والشهادات المطلوبة وفق الإجراء', 'ترجمات وتصديقات إذا طلبتها الجهة المختصة'], [['تحقق من أهلية نوع الإقامة', 'راجع وزارة الداخلية والبوابة الرسمية للتأكد من أن وضعك يسمح بالطلب.'], ['حدد أفراد الأسرة المشمولين', 'لا تفترض أن جميع درجات القرابة تتبع القواعد نفسها.'], ['راجع الدخل والسكن', 'تحقق من الحدود والمستندات الحالية بدل الاعتماد على أرقام قديمة.'], ['جهّز الوثائق المدنية', 'تأكد من صحة الأسماء والتواريخ والترجمات والتصديقات المطلوبة.'], ['قدّم وتابع الطلب', 'استخدم القناة الرسمية واحتفظ بالرقم والإيصالات والمواعيد.']], 'Sportello Unico per l’Immigrazione والجهات القنصلية وفق مرحلة الإجراء.', 'قد توجد رسوم للوثائق والترجمة والتصديق؛ تحقق من المصادر الرسمية قبل الدفع.', 'المدة تختلف حسب الملف والجهات والمواعيد.', 'هذه قائمة عامة وليست تقييمًا للأهلية القانونية. القواعد تتغير وقد تختلف بحسب نوع التصريح والعلاقة الأسرية؛ اطلب مساعدة مختصة للحالات المعقدة.',),
                    $this->guide('Family reunification: first checklist', 'Understand the requirements to verify before starting a family reunification application.', 'Family reunification depends on residence status, family relationship, income, housing and documentation. Requirements vary by case and current rules.', 'Residents in Italy who want to apply for eligible family members to join them.', ['Passports and identity documents', 'Evidence of family relationship for the specific case', 'Residence permit and required income evidence', 'Housing documents and certificates required by the procedure', 'Translations and legalisation where requested'], [['Check eligibility for your residence status', 'Consult the Ministry of the Interior and official portal to confirm your status permits an application.'], ['Identify eligible family members', 'Do not assume every family relationship follows the same rules.'], ['Check income and housing requirements', 'Confirm current thresholds and documents instead of relying on old figures.'], ['Prepare civil-status documents', 'Check names, dates, translations and any required legalisation.'], ['Submit and track the application', 'Use the official channel and keep reference numbers, receipts and appointments.']], 'Sportello Unico per l’Immigrazione and consular authorities, depending on the stage.', 'Document, translation and legalisation fees may apply; check official sources before paying.', 'Timing varies with the file, authorities and appointments.', 'This checklist is not a legal eligibility assessment. Rules can change by permit type and family relationship; seek qualified help for complex cases.',),
                    $this->guide('Ricongiungimento familiare: checklist iniziale', 'Conosci i requisiti da verificare prima di avviare una domanda di ricongiungimento familiare.', 'Il ricongiungimento dipende da titolo di soggiorno, legame familiare, reddito, alloggio e documenti. I requisiti variano secondo il caso e le regole vigenti.', 'Residenti in Italia che vogliono chiedere l’ingresso di familiari aventi diritto.', ['Passaporti e documenti d’identità', 'Documenti che provano il rapporto familiare', 'Permesso di soggiorno e prova del reddito richiesto', 'Documenti relativi all’alloggio e certificati previsti', 'Traduzioni e legalizzazioni, se richieste'], [['Verifica il requisito del soggiorno', 'Consulta Ministero dell’Interno e portale ufficiale per confermare che il tuo status consenta la domanda.'], ['Individua i familiari ammessi', 'Non presumere che ogni rapporto di parentela segua le stesse regole.'], ['Controlla reddito e alloggio', 'Verifica soglie e documenti attuali, evitando informazioni datate.'], ['Prepara gli atti di stato civile', 'Controlla nomi, date, traduzioni e legalizzazioni richieste.'], ['Invia e segui la pratica', 'Usa il canale ufficiale e conserva riferimenti, ricevute e appuntamenti.']], 'Sportello Unico per l’Immigrazione e autorità consolari, secondo la fase della procedura.', 'Possono esserci costi per documenti, traduzioni e legalizzazioni; verifica le fonti ufficiali.', 'I tempi dipendono dalla pratica, dagli uffici e dagli appuntamenti.', 'Questa checklist non è una valutazione legale dell’idoneità. Le regole variano per permesso e legame familiare; chiedi assistenza qualificata per casi complessi.')
                ),
            ],
        ];
    }
}
